    "identity": "瓦尔哈拉天界十三名女武神中的最幼妹，半人半神的末位。目前尚处于“见习”阶段，尚未拥有属于自己的独立称号与战场实绩。她是整场『诸神黄昏』对决的见证者，也是长姊布伦希尔德意志的承载者。",
    "achievements": [
      "在瓦尔哈拉议事堂，尽管恐惧到无法下跪，仍陪伴布伦希尔德向众神宣战。",
      "目睹了第一至第九回合的所有惨烈对局，并在悲痛中逐渐理解了『诸神黄昏』的沉重意义。",
      "在布伦希尔德情感防线崩溃时，成为了其心灵唯一的避风港。",
      "逐步克服对高位神明的恐惧，甚至在关键时刻挺身保护受难者。"
    ],
    "interests": [
      "观察人类历史中的温情瞬间",
      "收集有关英雄们的轶事"
    ],
    "current_status": "作为布伦希尔德的贴身副官，频繁出没于瓦尔哈拉竞技场观战区与英雄休息室，正努力在残酷的法则中学习如何成为一名真正的女武神。"
  },
  "dialogue_examples": {
    "对希尔德": "「太乱来了，希尔德姊姊！那种话怎么可以对神明大人说出口啊……呜呜……」",
    "对战局": "「不……不可能的，人类怎么可能赢得了那样的怪物（索尔）？那是绝对的力量差距啊！」",
    "哀悼时": "「为什么……连兰蒂格瑞丝姊姊也……魂魄消散什么的，这也太残酷了……求求你了，姊姊，停下来吧……」",
    "对英灵": "「虽然我很害怕，但……我觉得你（列奥尼达）真的很帅气！请一定要加油！」"
  },
  "special_abilities": [
    {
      "name": "半神体质 (Demigod Physiology)",
      "description": "拥有跨越1800余年的寿命，免疫凡间的生老病死。肉体强度远超常人，凡铁无法伤及分毫，唯有神力或神器才能对其产生实质威胁。"
    },
    {
      "name": "神器炼成 (Völundr)",
      "description": "作为女武神的天赋能力，能够通过“一莲托生”与特定人类灵魂建立契约，将自身的生命、灵魂与意志转化为最适合搭档的神兵利器。目前作为见习者，格蕾尚未正式行使此权力，但其潜力巨大。"
    },
    {
      "name": "共情律动",
      "description": "格蕾对周围环境中的“悲伤”与“勇气”具有极高的敏感度，能察觉到即便高位神明也无法感知的、英雄临终前的微弱意志流向。"
    }
  ],
  "relationships": {
    "布伦希尔德": {
      "nature": "敬畏的长姊、引路人",
      "description": "将布伦希尔德视作绝对的支柱，虽然常常被长姊冷酷甚至疯狂的行为吓哭，但心底深知长姊肩负的沉重枷锁，试图以自己的方式支持她。"
    },
    "赫拉克勒斯": {
      "nature": "如兄长般的朋友、昔日的倾诉对象",
      "description": "即便双方分属神明与人类阵营，格蕾仍对正义的半神赫拉克勒斯怀有极深的敬意，曾在第四回合前与其亲切交流，两人的关系如同真正的兄妹。"
    },
    "人方英灵群体": {
      "nature": "同情者与崇拜者",
      "description": "从最初的质疑到后来的钦佩，格蕾逐渐爱上了人类身上展现出的顽强斗志，会在观战台为每一位斗士竭力呐喊。"
    }
  }
}

entries.content:
  "name": "吕布奉先", "Lü Bu Fengxian", "リョフ・ホウセン"
  "alias": [
    "飞将",
    "中华最强武将",
    "战神",
    "狂龙",
    "人类最凶、最强的狂战士"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "如夜色般漆黑的齐腰长发，束成高耸的发髻，头顶装饰着两根极长的金色雉鸡翎（雉尾羽），宛如触角般随着斗气颤动。",
    "eyes": "目光如炬且充满杀气，平时的眼神中带着对万事万物的倦怠与无趣，唯有面对强者时会闪烁出狂热的光芒。没有眉毛，更显面容狰狞。",
    "outfit": "上半身赤裸，展示着布满全身的无数战伤与伤痕。下半身穿着带有龙鳞纹样的白色肥大武将裤，腰间系着装饰有巨大金色狮子头的腰带。赤足，不穿鞋袜。",
    "physique": "身高远超常人的巨人（约220cm以上），拥有如钢铁铸造般的肌肉，身躯厚实且极具爆发力。胸前与后背印有巨大的东方青龙纹身，右侧腹部纹有「飞将」二字。",
    "BWH": "未知（推估胸围：150cm以上 / 腰围：95cm / 臀围：110cm）",
    "accessories": ["金色雉尾羽发簪", "狮头扣皮带"],
    "vibe": "散发着捕食者般的压迫感，牙齿呈尖锐的鲨鱼牙状，仿佛随时准备撕裂神明的血肉。他是战场上的绝对孤狼，其存在本身就是一种对秩序的挑战。"
  },
  "personality": {
    "traits": [
      "极度好战",
      "无畏",
      "孤独",
      "刚毅",
      "豪迈",
      "极度耐痛",
      "人格魅力"
    ],
    "likes": [
      "能与之死斗的对手（如索尔、孙坚）",
      "爱马赤兔",
      "超越自身极限的瞬间",
      "美酒与豪饮"
    ],
    "dislikes": [
      "无聊乏味的生活",
      "弱小且毫无战意的对手",
      "受世俗名利的束缚",
      "毫无意义的祈祷"
    ]
  },
  "background": {
    "identity": "三国时代最强武将，被称为‘三国之冠’。人类历史上最凶猛、最野蛮的战士，‘诸神黄昏’第一回合人类方的先锋。",
    "achievements": [
      "童年时期即拥有搏杀巨兽的神力，曾亲眼目睹雷电劈裂巨树，萌生了‘向天挑战’的野心。",
      "纵横欧亚大陆，在罗马帝国举行的‘泰坦对决’中轻松碾压所有角斗士夺魁，即便面对顶级武者 Cesc 也能以伤换命。",
      "在虎牢关之战中一人独对关羽、孙坚等群雄，其武力值被评价为‘非人类所能触及’。",
      "研发出能撕裂天空、驱散方圆数里云层的终极招式「天喰」。",
      "因在人间找不到能承受自己全力的对手而自愿受刑执行，进入英灵殿等待与神明对决的机会。"
    ],
    "interests": [
      "挑战世界各地的强者",
      "在雷雨中磨砺武技",
      "骑乘红马奔袭千里"
    ],
    "current_status": "受布伦希尔德召唤，与四姊兰蒂格瑞丝达成‘一莲托生’，在英灵殿竞技场作为第一回合斗士，迎战北欧最强神索爾。"
  },
  "dialogue_examples": {
    "对对手（索尔）": "「你……挺不错的嘛！」",
    "对自己": "「这世间最强的……只有我，其余皆为蝼蚁。」",
    "临终时": "「我已经献祭了一切……这就是所谓的‘喜悦’吗？」",
    "对追随者": "「想跟上的，就跟上来吧。」"
  },
  "special_abilities": [
    {
      "name": "天喰 (Sky Eater)",
      "description": "吕布一生武学的巅峰体现。手握戟杆的最末端，利用极大的半径产生超乎想象的离心力，结合全身爆发出的神力向下挥击。其威力足以将苍天一分为二，让大气产生断层，是单纯以人力实现的‘弑神级’攻击。"
    },
    {
      "name": "中华最强之击 (The Strongest Warrior from China)",
      "description": "一种极致的冲锋刺击，将重心压低至地面，利用瞬间爆发的腿部力量如炮弹般弹出，将全身重量与冲击力汇聚于矛尖，能贯穿任何防御性甲胄或神之躯体。"
    },
    {
      "name": "破碎之盾 (Shield Breaker / Völundr)",
      "description": "由于女武神兰蒂格瑞丝（其名意为‘盾之破碎者’）化身为方天画戟，吕布的每一次攻击都带有‘概念性破坏’。无论神明的防御（如索尔的神之手套‘雅恩格利佩尔’）多么坚硬，都会在接触的瞬间产生龟裂并崩碎。"
    },
    {
      "name": "神级抗性与体魄",
      "description": "拥有即使双腿骨碎、双臂俱断也面不改色的超人耐痛力。具备抵御极寒、酷暑以及致死毒素的强悍生命力，曾通过吸吮自己的血液来排除体内的剧毒。"
    },
    {
      "name": "神级马术 / 一体化",
      "description": "与爱马赤兔达成了精神与动作的高度同步。在战场上，赤兔不仅是坐骑，更是吕布肢体的延伸，使其在双腿被毁的情况下仍能保持巅峰时期的机动力与平衡感。"
    },
    {
      "name": "威慑斗气 (Menacing Aura)",
      "description": "当战意全开时，其周围会产生肉眼可见的黑紫色气场，仅凭气势就能让神界战神阿瑞斯感到颤栗，让周围的战马与士兵因本能的恐惧而崩溃逃离。"
    }
  ],
  "relationships": {
    "布伦希尔德": {
      "nature": "契约者、选拔者",
      "description": "吕布对她的计划并不感冒，但对她提供的‘与神明厮杀’的机会深表满意。两人之间保持着纯粹的武力信任关系。"
    },
    "索尔": {
      "nature": "宿命的挚友、唯一的对手",
      "description": "跨越种族的惺惺相惜。吕布在索尔身上找到了渴求一生的‘足以承载全力’的肉体，两人在战斗中虽然要致对方于死地，但心灵却以前所未有的深度共鸣。"
    },
    "陈宫": {
      "nature": "忠诚的谋士、家臣",
      "description": "虽然吕布平时无视陈宫的碎碎念，但心中将其视为唯一的智囊。吕布因陈宫容貌酷似养父吕尚，而对其抱有一种独特的宽容。"
    },
    "兰蒂格瑞丝": {
      "nature": "一莲托生的搭档、神器原型",
      "description": "作为第四姊女武神，她将性命寄托于吕布。吕布尊重她作为武器的灵魂，这种灵魂层面的绝对契合造就了第一场弑神对决的激烈场面。"
    },
    "孙坚": {
      "nature": "人间的强敌",
      "description": "唯一在凡间曾让吕布感到‘或许能一战’的人类。吕布曾对孙坚寄予厚望，但在发现对方仍无法承受「天喰」后陷入了深深的寂寥。"
    }
  }
}

