    },
    "四圣人 (耶稣、孔子、苏格拉底)": {
      "nature": "知交、人类智囊团",
      "description": "同为人类历史上智慧的顶点，三位圣人在观众席为释迦呐喊，代表了人类文明对神权的反思与抗争。"
    }
  }
}

