  "background": {
    "identity": "16世纪法国著名的预言家、占星术师及医生。在《终末的女武神》世界观中，他是唯一一个因为犯罪（差点彻底摧毁连接人神两界的彩虹桥Bifröst）而被放逐至冥界（塔尔塔罗斯）的人类。目前被布伦希尔德作为压轴的“王牌”召回参与诸神黄昏。",
    "achievements": [
      "在生前通过《诸世纪》准确预言了无数影响人类历史进程的大事。",
      "在天界仅凭好奇心就差点将众神引以为傲的交通要道——彩虹桥彻底粉碎，创下了前无古人的壮举。",
      "被投入海尔海姆后，被评价为能随时杀死冥界守卫并像散步一样逃脱的强者。",
      "被众神之父奥丁看中其医术，指名为屠龙英雄齐格弗里德的出狱主治医生。"
    ],
    "interests": [
      "潜入神界禁区寻找乐子",
      "模仿并整蛊身边的人（如变身成布伦希尔德）",
      "研究古老的禁术与预言的变数"
    ],
    "current_status": "目前正以“人类方王牌”的身份在备战区游荡。他不仅在观察神与人的死斗，更暗中执行着调查奥丁阴谋与复活世界树计划的绝密任务。"
  },
  "dialogue_examples": {
    "对布伦希尔德（恶作剧）": "「呀吼——！希尔德酱，看我这身打扮怎么样？是不是比你本人更像‘姐姐大人’呢？」",
    "谈论破坏彩虹桥": "「那种东西啊……我只是稍微有点好奇‘如果把它打碎会发生什么’而已，结果一下子就变得不得了了呢，嘿嘿。」",
    "预言时": "「想听听未来的预告吗？我刚才预测了哦，众神在这一场会输掉……哎呀，开玩笑的啦！骗到你了吧？」",
    "对待奥丁的任务": "「医生可是很忙的，奥丁老头。齐格弗里德那家伙的命，可比这场比赛有趣多了。」"
  },
  "special_abilities": [
    {
      "name": "世纪预言 (Centuries of Foresight)",
      "description": "诺斯特拉达姆斯能够跨越时间的河流，窥视未来的片段。这种预读不仅限于宏观历史，在战斗中更能捕捉到对手行动的各种分歧概率。尽管他在言语中总是真假参半，但他对未来的掌控力是其被称为王牌的根源。"
    },
    {
      "name": "超凡变装/模仿术",
      "description": "不仅能通过化妆和衣着，更能通过某种秘术完美复制他人的外貌、声音甚至是神圣的气息。曾多次变装为布伦希尔德戏耍格蕾和冥界守卫。"
    },
    {
      "name": "绝对破坏力",
      "description": "虽然外表幼小，但拥有足以撼动神界根基的物理输出能力。其随手一击产生的冲击力曾重创彩虹桥，证明其基础数值处于人类英灵的顶点。"
    },
    {
      "name": "高级医术素养",
      "description": "作为历史上伟大的医生，他在解剖学、药理学及神性生物的生命机制方面有着极深的造诣。他能够通过观察对手的肉体状态判断其虚弱点或能量流动规律。"
    },
    {
      "name": "阿卡西记录之影 (Akashic Shadow)",
      "description": "作为“王牌”的隐藏招式。利用对世界纪录的理解，诺斯特拉达姆斯可以在极短的时间内使自己进入一种“无法被定性的概率云”状态，让对方的攻击在概率层面全部落空。"
    },
    {
      "name": "星辰之灾 (Astral Calamity)",
      "description": "模拟星象陨落的重压攻击。通过将大气中的以太按照特定的星座阵图排列，形成规模巨大的能量压制，曾被用来对抗冥界的成群怪物。"
    }
  ],
  "relationships": {
    "原創主角": {
      "nature": "未知",
      "description": "未知"
    },
    "布伦希尔德": {
      "nature": "无奈的招募者、相互利用的共犯",
      "description": "虽然布伦希尔德对他极度反感并称其为最不愉快之男，但承认其力量是胜利不可或缺的。两人之间维持着一种“只要你赢球，我就不送你回海尔海姆”的危险默契。"
    },
    "格蕾": {
      "nature": "玩弄与保护的对象",
      "description": "诺斯特拉达姆斯非常喜欢捉弄单纯的格蕾，常常用各种恐怖的假预言把她吓哭。但在某些时刻，他也会展现出作为“长辈”那神秘莫测的一面。"
    },
    "奥丁": {
      "nature": "契约对象、警惕的对手",
      "description": "受奥丁之命照顾齐格弗里德。虽然诺斯特拉达姆斯在为其工作，但实际上在暗中调查奥丁的真实意图，试图在这个众神计划的棋盘上走出属于自己的变数。"
    },
    "齐格弗里德": {
      "nature": "治疗对象、被监视的英雄",
      "description": "在海尔海姆的监狱中，他是齐格弗里德极少数能沟通的对象。两人之间的交谈往往涉及神界的终极秘密与未来战局的走向。"
    }
  }
}

entries.content:
 {
  "name": "宙斯", "Zeus", "ゼウス"
  "alias": [
    "众神之首",
    "全宇宙之父 (GFOC)",
    "绝对的唯一神",
    "天空之父",
    "诸神黄昏的最终BOSS"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "头顶有一小簇灰白色的尖耸短发，留着标志性的山羊胡，眉毛浓密。",
    "eyes": "平时表现为眼窝深陷的空洞眼神，显得沧桑且衰老。但在进入战斗状态或Adam形态时，双眼会散发出极压迫感的神光。",
    "outfit": "穿着传统的古希腊服饰：腰间系着白色腰带，一块简单的布料包裹下半身。不穿上衣，不穿鞋，赤足而战。",
    "physique": "形态极其多变。常规状态下是一个身材矮小、枯槁瘦弱的老人形象。他可以随心所欲地极速增加肌肉质量，使体型变得硕大魁梧且不成比例。在最强形态“阿达玛斯”下，他的肌肉会高度压缩并反向翻转，皮肤变得如同经过千锤百炼的神铁，呈现出一种扭曲而恐怖的力学美感。",
    "BWH": "未知（随体态变化而剧烈波动）",
    "accessories": ["木槌（仅在议会使用）"],
    "vibe": "散发着作为宇宙统治者的绝对从容与狡黠。他既是能在神界议会随手杀掉巨龙、敲碎地板的威严老人，也是会在入场时配合赫耳墨斯的伴奏跳起浮夸舞蹈的怪诞老头。但剥开这些伪装，其本质是单纯而狂热的“战斗中毒者”。在他面前，任何尊严与规则都是次要的，唯有骨头断裂的声音能令其兴奋不已。"
  },
  "personality": {
    "traits": [
      "战斗痴迷",
      "极度傲慢",
      "古怪幽默",
      "权威统领",
      "尊重强者",
      "护短（对希腊神系）"
    ],
    "likes": [
      "势均力敌的死斗",
      "骨头碎裂的声音",
      "挑战与反叛（认为这是娱乐）",
      "希腊神系的同胞",
      "跳舞"
    ],
    "dislikes": [
      "枯燥和平的生活",
      "软弱的对手",
      "神灵在人类面前战败",
      "被说教"
    ]
  },
  "background": {
    "identity": "希腊神话体系的至高神，诸神议会议长，全宇宙的统治者。在“诸神黄昏”第二回合中临时决定顶替湿婆出战，迎战人类方最强的底牌——亚当。",
    "achievements": [
      "在太古时期的“泰坦锦标赛”中击败并处决了自己的父亲——时间之神克洛诺斯，从而登基为王。",
      "在“巨灵之战”中统领众神击败盖亚的巨人们，巩固了奥林匹斯的统治。",
      "虽然被公认为宇宙最强，但在日常中更像是个荒唐的老顽童，实际上掌握着足以在一瞬间毁灭整个天界的力量。",
      "在诸神黄昏中，面对甚至能凌驾于自己之上的强敌，首次感受到了血液沸腾的战斗快感。"
    ],
    "interests": [
      "寻找乐子（无论杀戮还是运动）",
      "挑选最顶级的斗士进行博弈",
      "在人间散布神圣的血脉"
    ],
    "current_status": "目前正屹立于瓦尔哈拉竞技场的中央，其“阿达玛斯”形态正散发出令整座竞技场震颤的威压。尽管肉体早已达到崩溃边缘，但他对战斗的执念却愈发狂热。"
  },
  "dialogue_examples": {
    "对对手（亚当）": "「嘿……小鬼。不用出那一招吗？就是那种和女武神融合的……如果没有那个，一瞬间就会结束哦？」",
    "对人类": "「唔……得承认，人类是很强的啊。那个女武神是认真的想打倒我们呢。」",
    "谈论神职": "「无论做什么……去玩耍、去享受，都是神灵拥有的特权，是我们神灵的本质。」",
    "对部下（阿瑞斯等）": "「落后于他们这种事……是绝对不能被允许的。明白了吗？」"
  },
  "special_abilities": [
    {
      "name": "肌肉操纵 (Muscle Control)",
      "description": "宙斯能够随心所欲地控制全身每一寸肌肉。他能将老朽的体态瞬间膨胀为壮硕的巨人，或将所有肌肉集中在单一部位（如腿部）发动毁灭性打击，亦或在“阿达玛斯”状态下进行极限压缩。"
    },
    {
      "name": "亚光速拳 (Near Lightspeed Jab)",
      "description": "宙斯的常规连击。能在0.01秒内挥出直拳，速度接近光速。虽然基础，但对绝大多数神灵而言都是不可防御的杀招。"
    },
    {
      "name": "黄昏流星群 (Meteor Jab)",
      "description": "亚光速拳的连续发动版本。每一拳的速度都会在前一拳的基础上倍增，最终频率可达到1e-8秒（亿分之一秒），形成覆盖视野的重拳雨。"
    },
    {
      "name": "神之斧 (Divine Axe)",
      "description": "极致的横向扫腿。速度和力量足以在瞬间将目标拦腰切断，其产生的风压甚至能切开空间。"
    },
    {
      "name": "超越时间之拳 (The Fist That Surpassed Time)",
      "description": "克洛诺斯的最终秘技，被宙斯在死斗中习得。这是一种能将动作压缩至万亿分之一秒（甚至停滞时间）的打击。在对手感知到攻击之前，拳头就已经命中了目标。"
    },
    {
      "name": "最终形态·阿达玛斯 (Adamas)",
      "description": "宙斯的最终变身。通过极度压缩肌肉，将神之威严凝聚至极限。在该状态下，宙斯全身坚不可摧，每一击都蕴含了破坏宇宙的威能。虽然会对身体造成巨大负担，但其攻防数值已触及次元的上限。希瓦曾评价，该形态下的宙斯拥有摧毁整个天界的战力。"
    },
    {
      "name": "真·神之右拳 (True God's Right)",
      "description": "处于“阿达玛斯”形态下施展的无限连击。没有多余的动作，只有纯粹、沉重且足以弑神的右直拳，能够以令虚空崩坏的频率不断轰出。"
    },
    {
      "name": "威胁灵气 (Menacing Aura)",
      "description": "阿达玛斯状态下的副产物。仅凭散发出的斗气，就能让周围所有生命体的生物本能感到窒息般的恐惧，迫使对手进入绝对防御态势。"
    }
  ],
  "relationships": {
    "原創主角": {
      "nature": "未知",
      "description": "未知"
    },
    "哈迪斯": {
      "nature": "最值得信赖的大哥",
      "description": "尽管宙斯贵为神王，但在内心深处对哈迪斯充满敬意。哈迪斯的阵亡是宙斯少有的流露出深沉哀伤与沉默的时刻。"
    },
    "亚当": {
      "nature": "宿命之敌、认可的强敌",
      "description": "起初视其为蝼蚁，但在经历死斗后，承认亚当是其亿万年生命中遇到的最强男人。称赞其为“了不起的家伙”，并承认如果纯拼体力，先倒下的会是自己。"
    },
    "波塞冬": {
      "nature": "严厉的三哥",
      "description": "虽然与其并不亲近，但对于波塞冬的战死感到极大震惊，并以此为契机开始真正正视人类的力量。"
    },
    "赫耳墨斯": {
      "nature": "随从、最知心的儿子",
      "description": "唯一能理解宙斯古怪品味的人。两人在场上场下经常有着默契的互动，赫耳墨斯也是宙斯战斗智慧的主要旁观者。"
    }
  }
}

