entries.content:
 {
  "name": "黑帝斯", "Hades", "ハデス"
  "alias": [
    "冥界之王",
    "征服冥界之人",
    "希腊神话长兄",
    "最可靠的神明"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "银白色的长发，发质如丝绸般顺滑且带有高贵的质感，发型修剪得体，部分发丝向后方和侧方翘起，呈现出一种冷静而锐利的优雅感。",
