    "别西卜": {
      "nature": "友人、被其意志折服的晚辈",
      "description": "黑帝斯是别西卜心目中唯一可以称之为“朋友”的人。黑帝斯不仅教导了别西卜如何面对体内的诅咒，还将阿普米乌斯之杖赠予他，变相地赋予了他生存的意志。"
    },
    "阿达玛斯": {
      "nature": "惹祸的二弟、暗中的资助者",
      "description": "即便阿达玛斯发动叛乱被处决，黑帝斯依然不忍放弃他，秘密请求别西卜将其重组为半机器人。黑帝斯始终在履行作为长子“一个都不能少”的诺言。"
    },
    "始皇帝": {
      "nature": "敬重的死斗对手、异端的王",
      "description": "黑帝斯起初视其为复仇之路上的障碍，但在战斗中逐渐理解了对方肩负的民众之重。黑帝斯，将其视为与波塞冬同等规格的、令人尊重的“真王”。"
    }
  }
}

