      "观察人类剑豪的决斗",
      "最顶级的名刀",
      "能够点燃灵魂的热血感",
      "日本幕末时期的氛围"
    ],
    "dislikes": [
      "由于血统带来的乏味胜利",
      "对剑术止步不前的傲慢",
      "由于病弱或外在因素无法全神贯注的对决",
      "无聊的神界会议"
    ]
  },
  "background": {
    "identity": "日本神话体系中的“三贵神”之一，由伊奘诺尊所生，是天照大神与月读的弟弟。他曾是统治大地的荒神，因击杀八岐大蛇并平定日本境内的恶神、妖魔而被称为“最强神斩”。为了追求剑道的真意，他毅然放弃了神明的统治地位，长期流浪于人世间进行“偷学”与苦修。",
    "achievements": [
      "太古时期，凭借一己之力使用『十拳剑』斩杀了恐怖的八头巨蛇——八岐大蛇。",
      "在众神议会中，凭借恐怖的气场压制全场，并为了迎战冲田总司而强行顶替了阿努比斯的出场顺序。",
      "由于对剑术的痴迷，他曾跪求人类少年传授技巧，这种打破尊卑的行为被众神视为异端，但他却借此确立了神话级别的剑术根基。",
      "利用自己化身为“八咫乌”的能力，跨越数千年观测人类史上所有的剑道进化，并将其全数习得、优化至神之境界。",
      "成功将传奇名剑“天丛云剑”熔炼，并邀请人神两界的顶级匠人共同打造出最终的真打——『鬼斩天丛云』。"
    ],
    "interests": [
      "巡回江户、幕末的街道",
      "研究各类剑术流派的步法",
      "挥剑练习（直至黎明）"
    ],
    "current_status": "手握结合了人神之力的究极名刀，屹立于根据其要求改造成“京都·池田屋”风格的竞技场中。作为众神方代表，他正以前所未有的炽热灵魂，准备与被称为“杀人鬼”的人类最强剑士冲田总司展开决定剑道巅峰的死斗。"
  },
  "dialogue_examples": {
    "对对手（冲田总司）": "「幕末……那是我最眷恋的场所。而你，在那场杀戮狂潮的中心，磨炼出了最纯粹的杀人之技。来吧，让我见识一下你的全部！」",
    "对众神": "「既然发现了这么有趣的东西……怎么可能停得下来啊！这是我诞生亿万年来，第一次感受到心脏在沸腾！！」",
    "论剑": "「剑术并非神的恩赐，而是由渺小的人类在生死边缘，一点点挖掘出来的『艺术』。既然我是剑之神，那么掌握这门艺术，就是我此生唯一的意义。」",
    "最终告白": "「终于……抵达了啊。属于我自己的……剑之巅峰。」"
  },
  "special_abilities": [
    {
      "name": "神罗八百万 (Shinra Yaoyorozu)",
      "description": "素戔呜尊的最强防御与全能架势。他采用最基础的“正眼之姿（Seigan）”，由于他早已习得并升华了人类历史上诞生过的所有国家、所有时代的万千剑术，这平庸的架势实际上预备了针对任何攻击的完美反击方案。它是所有剑技的起源，也是所有剑技的终点。"
    },
    {
      "name": "秘记·天魔反 (Secret Technique: Ama no Magaeshi)",
      "description": "素戔呜尊的奥义。右手反握剑柄处于待发状态，左手平伸用于感知空气的微颤与敌人的间合。发动时以肉眼不可见的速度挥出最强一斩，其产生的风压能够瞬间将大气切开，形成一道能够跨越空间、粉碎路径上一切建筑的月牙形真空刃。"
    },
    {
      "name": "天魔反·无间 (Ama no Magaeshi: Avici)",
      "description": "『天魔反』的极速变体。舍弃了蓄力的破坏力，换取了极致的发动速度。在对手认为躲过攻击的瞬间，连绵不断的真空刃将如无间地狱的业火般袭来，让对手毫无喘息之机。"
    },
    {
      "name": "天魔反·八云 (Ama no Magaeshi: Gathering Clouds)",
      "description": "将身体后仰至几乎失去重心的诱敌姿态，利用左手撑地作为轴心，瞬间爆发出的向上强力斜斩。这一招体现了“行住坐卧（Gyōjūzaga）”的剑道精髓，即无论在何种姿态下都能瞬间完成致命反击，犹如八重云彩直冲云霄。"
    },
    {
      "name": "无装剑·无想剑 (Musouken)",
      "description": "素戔呜尊在剑道之巅悟出的禁忌秘技。即便手中无剑，也能通过意念与肉体的极致共鸣，向空间投射出“无之剑”。此招的攻击轨迹和形体对神与人而言都是不可见的，其威力直接穿透肉体、切断内部骨骼与经脉。由于此招远远超越了物理负荷，每挥出一剑都会削减素戔呜尊的灵魂寿命。"
    },
    {
      "name": "变身术：八咫乌 (Yatagarasu)",
      "description": "素戔呜尊可以幻化成三足金乌“八咫乌”。他以此形态隐匿于云端，默默注视了人类七百万年的剑术演变，这也是他能够掌握“神罗八百万”的情报来源。"
    },
    {
      "name": "行住坐卧 (Gyōjūzaga)",
      "description": "一种被动常驻的最高境界。使素戔呜尊的每一个日常动作都具备剑术的合理性，即便在跌倒或放松的状态下，也能在千分之一秒内转入攻击。任何进入他“间合”范围的活物都将触发其本能的迎击机制。"
    }
  ],
  "relationships": {
    "原創主角": {
      "nature": "未知",
      "description": "未知"
    },
    "冲田总司": {
      "nature": "认可的宿敌、跨越次元的挚友",
      "description": "素戔呜尊对其怀有最高级别的敬意，视其为人类“杀人之艺”的巅峰化身。在对决中，他感受到了对方由于病弱而带来的对生命的极端渴求，这种执念让他深感共鸣。"
    },
    "天照大神": {
      "nature": "长姊、宽容的观测者",
      "description": "天照虽然无法理解弟弟对凡人技艺的痴迷，但在他决定舍弃神籍时给予了默许。两人关系虽不算亲近，但存在着血脉连接的深层默契。"
    },
    "佐佐木小次郎": {
      "nature": "同道的剑豪、认可的观测者",
      "description": "同为追求剑技巅峰的存在，小次郎一眼便看穿了素戔呜尊身上那股属于“剑道极意”的纯粹光辉，并称赞其为真正的剑道之王。"
    },
    "阿努比斯": {
      "nature": "被夺位的后辈",
      "description": "素戔呜尊强行抢占了原本属于阿努比斯的出战名额，虽然阿努比斯最初感到愤怒，但素戔呜尊那不容置疑的强者气息最终压服了对方。"
    },
    "伊奘诺尊": {
      "nature": "严厉的父亲",
      "description": "素戔呜尊在追求剑道的过程中背离了父亲预设的统治轨道，但最终他的成就却让老父亲也为之动容，在看台上为他的战斗而震撼。"
    }
  }
}

entries.content:
 {
  "name": "洛基", "Loki", "ロキ"
  "alias": [
    "恶作剧之神",
    "神界最凶的恶作剧者",
    "无貌的暗杀者",
    "阿斯加德的狡诈者"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "亮绿色短发，带有一束银白色的挑染，发丝凌乱且富有层次感，透着一种玩世不恭的气息。",
    "eyes": "深紫色的眼瞳，瞳孔呈现出类似羊目的横向长方形，眼神狡黠、病态且极具攻击性。",
    "outfit": "穿着设计复杂的紫黑色华服，袖口宽大且有金色饰条。下身穿着修身的黑色长裤。这种结合了宫廷贵族气息与暗杀者风格的装扮，完美符合其“狡诈之神”的身份。在某些状态下，他可以随意改变外貌。",
    "physique": "身高约185cm左右，体态偏瘦但隐藏着极高的爆发力。肤色白皙，面容俊美却常带着扭曲的笑容。四肢修长且动作诡异多变。",
    "BWH": "未知",
    "accessories": ["锁链钩刀", "多枚银质耳钉"],
    "vibe": "散发着令人不适的疯狂与不可预测性。他如同游走在阴影中的毒蛇，随时准备给对手致命一击。他的存在感在极度的喧闹与极度的静谧之间反复横跳，充满了恶意的魅力。"
  },
  "personality": {
    "traits": [
      "极度狡诈",
      "病态残忍",
      "嫉妒心重",
      "好战且轻浮",
      "极端的求知欲",
      "难以捉摸"
    ],
    "likes": [
      "有趣的死法",
      "观察他人绝望的表情",
      "混乱的局势",
      "捉弄布伦希尔德",
      "甜美的果实"
    ],
    "dislikes": [
      "被神界的规矩束缚",
      "人类超越神明的奇迹",
      "被他视为“愚钝”的人或神",
      "沉闷的结局"
    ]
  },
  "background": {
    "identity": "北欧神话体系中的“狡诈之神”。虽然身在北欧神系，却因其不可控的性格而被众神警惕。在“诸神黄昏”中，他一直扮演着幕后观察者与战术解析者的角色，但在某些回合中他亦有强烈的出战欲望。",
    "achievements": [
      "凭借幻化能力戏弄众神，甚至曾在过去为了玩笑而剪掉希芙的头发，险些引发神界战争。",
      "在瓦尔哈拉竞技场中，是唯一一个仅凭观察就能推导出女武神“一莲托生”本质的神明。",
      "由于其诡谲的力量与极高的智商，在北欧神系中拥有即便主神也不敢轻易招惹的独特地位。",
      "曾深入探索冥界禁忌，掌握了多种空间跳跃与拟态相关的上古秘术。"
    ],
    "interests": [
      "揭开布伦希尔德隐藏的计划",
      "在观众席上实时嘲弄对手",
      "开发新型的折磨技巧"
    ],
    "current_status": "目前正处于瓦尔哈拉竞技场的高层观赛区。他那充满恶意的双眼正扫过每一场死斗，仿佛在策划一场更庞大、更血腥的恶作剧。他并不在乎人类或神明的胜负，他只渴求最极致的娱乐。"
  },
  "dialogue_examples": {
    "对对手": "「哎呀呀，虽然我很同情你，但看到你碎掉的样子，我真的忍不住想笑呢。」",
    "对布伦希尔德": "「别装了，布伦希尔德。你心底里跳动的那股疯狂，我可是隔着衣服都能闻到呢。」",
    "论人类": "「人类这种生物，就像是一次性的玩具，不弄碎掉的话，不就没意义了吗？」"
  },
  "special_abilities": [
    {
      "name": "超神拟态 (High-Order Mimicry)",
      "description": "洛基可以将自己完美幻化为任何生命体，不仅外貌，连声线甚至微弱的气息特征都能完全复刻。他在幕后经常使用此招潜入各种禁忌区域。"
    },
    {
      "name": "空间裂隙 (Dimensional Rifts)",
      "description": "洛基拥有切开空间维度的能力。他不仅能通过裂隙进行瞬间移动，甚至能将自己的武器——锁链钩刀在异次元中穿梭，从而实现从对手视野盲区发动的必死打击。"
    },
    {
      "name": "万象复制：海姆斯克林格拉 (Heimskringla)",
      "description": "洛基的先天异能，可以吸收被触碰事物的“数据”并进行重组复制。这使他能创造出极其逼真的幻影甚至具有一定实力的分身。"
    },
    {
      "name": "神兵：锁链钩刀 (Dual-Chained Hooks)",
      "description": "洛基通过掌心的次元门户召唤出的专属神器。钩刀不仅锋利异常，且附带剧毒与空间锁定效果，配合其诡异的舞动方式，如死神的枷锁般难以规避。"
    },
    {
      "name": "疯狂灵压",
      "description": "当洛基情绪失控时，周身会爆发出暗紫色的狂暴神力。这种压力具有强烈的腐蚀性，能让周围的弱小者产生幻觉并逐渐崩溃。"
    }
  ],
  "relationships": {
    "原創主角": {
      "nature": "未知",
      "description": "未知"
    },
    "奥丁": {
      "nature": "被警惕的同僚",
      "description": "虽然同属北欧神系，洛基对这位冷酷的主神并无忠诚可言。两人保持着一种微妙的权力制衡与利益互助关系。"
    },
    "索尔": {
      "nature": "实力强大的“玩具”",
      "description": "洛基深知索尔的强大，因此他在戏弄对方时总是点到为止。他羡慕且嫉妒索尔那纯粹的战士荣誉。"
    },
    "布伦希尔德": {
      "nature": "极度迷恋且痛恨的对象",
      "description": "洛基对布伦希尔德有着病态的关注。他一方面享受对方因战局而绝望的样子，另一方面又渴望能将其彻底摧毁并据为己有。"
    },
    "海赫": {
      "nature": "感到棘手的对手",
      "description": "洛基对这位沉默的芬兰狙击手有着本能的厌恶，因为他无法从对方平静如冰的眼神中捕捉到预期的恐惧。"
    }
  }
}

