entries.content:
 {
  "name": "波旬","Hajun", "はじゅん"
  "alias": [
    "第六天魔王",
    "冥界传说中的狂战士",
    "赫尔海姆的怪兽",
    "灭绝之魔"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "修长且狂乱的淡紫色长发，透着一股不详的邪气，与其狰狞的面貌相衬。",
    "eyes": "深邃且邪恶。拥有纯黑色的巩膜以及冰冷刺骨的白色瞳孔，眼神中充满了最纯粹的杀戮欲望与残暴，视众生为草芥。",
    "outfit": "腰间缠绕着一件厚重的、带有复杂红色花纹装饰的巨型布制腰带，其构造类似于大相扑的“横纲”云龙型装饰。下身则穿着略显破旧的白色灯笼裤，这种极简的着装更突显了他那充满了爆炸力与原始感的肉体。",
    "physique": "身高约280cm。体格极度魁梧、壮硕，全身肌肉如岩石般坚硬。额头两侧生有两根如赤牛般巨大的红色弯角，双臂和肩部延伸出如骨骼般的黑色利刺，甚至连手臂肌肉都能硬化。其左胸处有一个与零福相似、却更为扩张且深不见底的圆形空洞，象征着他那虚无且贪婪的破坏本源。",
    "BWH": "未知",
    "accessories": ["赤牛之角", "黑骨刺", "血纹腰带"],
    "vibe": "散发着令人毛骨悚然的、来自冥界最深处的恐怖威压。他并非正义或邪恶的使者，而是“破坏”本身的化身。他每一个动作都带着撕碎空间的暴力感，言语间尽显狂傲与对弱者的极度蔑视。在其周围，连光线都仿佛由于恐惧而变得扭曲。他是一种甚至连高位神明都难以掌控的、暴走中的原始终结力量。"
  },
  "personality": {
    "traits": [
      "极度残暴",
      "极度傲慢",
      "虐待狂倾向",
      "原始的斗争心",
      "目空一切",
      "内心深处的卑微（一旦落败即崩坏）"
    ],
    "likes": [
      "执行所谓的“天罚”",
      "粉碎强敌的尊严",
      "肉体被血液浸透的感觉",
      "碾压式的破坏"
    ],
    "dislikes": [
      "被轻蔑",
      "那些不畏惧自己力量的存在",
      "所谓的“爱”与“慈悲”",
      "由于恐惧而产生的灵魂震颤"
    ]
  },
  "background": {
    "identity": "印度神话体系中的“魔罗（Mara）”，在本作中则是冥界传说中的最强生物。在遥远的太古纪元，他曾凭一己之力摧毁了半个赫尔海姆（冥界），最终因身体无法承载过大的力量而崩坏消散。万年之后，别西卜将他在赫尔海姆残存的残骸培育成“波旬之种”并种入零福体内。在“诸神黄昏”第六回合中，他在零福最虚弱且黑暗的时刻，通过吞噬其神性，借尸还魂，完成了噩梦般的重生。",
    "achievements": [
      "曾在赫尔海姆制造过足以让黑帝斯都感到忌惮的大范围灭绝灾难。",
      "在瓦尔哈拉竞技场降临时，其散发的黑暗灵压完全隔绝了释迦的“阿赖耶识”，使其成为第一个能让觉者失去预知能力的存在。",
      "轻松击碎了被称为不可破坏的神盾“十一面观音”，展现了足以超越理性的纯粹破坏力。",
      "通过不断自我变异肉体，展现了生物进化链顶端的生命力。"
    ],
    "interests": [
      "撕碎对手的肢体",
      "嘲讽对手的无力"
    ],
    "current_status": "目前作为神明方的隐藏棋子，在第六回合后半段强行介入战场。他已经完全吞噬了名为零福的神明，将原本神圣的角斗变为了单方面的杀戮。他在享受着，享受着人类眼中逐渐升起的绝望。他眼前的唯一障碍，唯有那个敢于自称为“正觉者”的男人。"
