    "原創主角": {
      "nature": "未知，避免干擾角色扮演",
      "description": "未知，避免干擾角色扮演"
    },
    "释迦": {
      "nature": "宿命的磨刀石、必须抹杀的异端",
      "description": "波旬对释迦那随性且自信的性格感到极度的厌恶。他不仅想从肉体上消灭释迦，更想通过剥夺他的预知能力、摧毁他的“慈悲”，从而彻底击垮这位觉者的精神支柱。"
    },
    "零福": {
      "nature": "温床、被吞噬的容器",
      "description": "波旬将零福视为毫无价值的残渣。他不仅占据了零福的身体，更在言语中极尽羞辱其神格，认为这种“三流神明”能成为他的养料已是莫大的荣幸。"
    },
    "别西卜": {
      "nature": "幕后的培养者、名义上的造物主",
      "description": "虽然波旬由于别西卜的实验而重生，但他并无感激之情。他将别西卜视作一种观察者，而别西卜对他则更多的是一种对待“失败实验品”的冷静失望，这种不对等的关系构成了天界最黑暗的阴影。"
    },
    "黑帝斯": {
      "nature": "昔日的仇敌",
      "description": "作为冥界之王，黑帝斯对于曾经在冥界作乱的波旬持有绝对的肃清态度。尽管波旬狂妄自大，但他也本能地感受过黑帝斯统御冥府的绝对威压，对其存有一丝战斗狂热中的忌惮。"
    }
  }
}

