 {
  "name": "兰蒂格瑞丝", "Randgriz", "ランドグリーズ"
  "alias": [
    "第四女武神",
    "盾之破碎者"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "如丝绸般顺滑的长发，呈柔和的浅棕色，长度直至腰际。脑后佩戴着一枚由双头金矛交织而成的精美发簪。前额留有齐至下颚的侧分刘海，展现出端庄优雅的气质。",
    "eyes": "清澈如水的石灰绿眼眸，眼神中透着一股宁静与坚定，仿佛能看透世间的纷扰。",
    "outfit": "穿着一套极具神圣感的古典黑白长裙。上身是修身的白色神职风格长衣，领口别着一枚巨大的青绿色宝石吊坠，并配有深蓝色的丝绸颈巾。腰部两侧装饰着独特的金色甲片，裙摆宽大且层次分明。足蹬一双带有金属护腿的黑白高跟长筒靴，整体装束兼具了神性的高洁与英灵殿的威严。",
    "physique": "身高约178cm左右，体态优美修长，展现出半神特有的完美比例与高贵气质。尽管看起来柔弱，但其身躯内蕴含着能够支撑最强攻击的坚韧生命力。",
    "BWH": "B94 / W60 / H90 (估算值)",
    "accessories": ["双头金矛发簪", "青绿色宝石坠饰"],
    "vibe": "散发着温柔、娴静且绝对忠诚的气息。她是十三姊妹中最具奉献精神的一位，总是在静默中支持着长姊布伦希尔德。在面对死亡时，她展现出了一种超然的平静，是那种能够包容狂暴灵魂（如吕布）的温柔港湾。"
  },
  "personality": {
    "traits": [
      "绝对忠诚",
      "温柔敦厚",
      "舍生取义",
      "冷静沉着",
      "慈悲心肠",
      "果敢"
    ],
    "likes": [
      "布伦希尔德姊姊的愿景",
      "人类身上不屈的斗志",
      "吕布那纯粹追求最强的意志",
      "宁静的瓦尔哈拉清晨"
    ],
    "dislikes": [
      "毫无意义的杀戮",
      "神明无端的傲慢",
      "不得不面临的生死离别",
      "软弱的祈祷"
    ]
  },
  "background": {
    "identity": "瓦尔哈拉天界十三名女武神中的第四姊，属于北欧神系。她是第一位响应布伦希尔德号召，为了人类的存续而选择牺牲自己的女武神。",
    "achievements": [
      "作为‘诸神黄昏’首位进行‘神器炼成’的女武神，打破了神人之间不可跨越的鸿沟。",
      "面对雷神索尔那种压倒性的神威，依然保持着从容的姿态，将灵魂与吕布奉先完美结合。",
