    "BWH": "B82 / W58 / H84 (估算值)",
    "accessories": ["长方形眼镜", "学士帽", "学者披风"],
    "vibe": "散发着浓厚的学术气息与知性魅力。她与那些狂放不羁的战将不同，即便在面对毁灭性的神威时，依然能保持学者的冷静与忠诚。她是对知识抱有敬畏、对职责绝对服从的优雅女性。"
  },
  "personality": {
    "traits": [
      "极度忠诚",
      "知性理性",
      "严谨负责",
      "关爱家人",
      "略显古板（针对教育）"
    ],
    "likes": [
      "古老的文献与知识",
