    "关于责任": "「就在这一刻，我们……已经融为一体了！！」",
    "日常闲暇": "「如果你能安静地读完这卷宗，我就不再追究你之前的懈怠了。」"
  },
  "special_abilities": [
    {
      "name": "神器炼成：神之刻痕手指虎 (Völundr - Brass Knuckles)",
      "description": "瑞吉蕾芙通过“一莲托生”与亚当达成的武器形态。她将自身知性的灵魂炼化为一副简洁而坚固的手指虎，装备于亚当的右手上。这一形态虽无华丽的修饰，却赋予了亚当击穿神明肉体、粉碎神性防御的绝对物理打击力。"
    },
    {
      "name": "力量痕迹·追溯 (Trace of Power)",
      "description": "瑞吉蕾芙的名字本身意为“力量的痕迹”。作为神器，她能够极大程度地增幅亚当“神虚视”在解析神技时的运算效率，协助亚当捕捉神明出招时那极其微弱的法则脉动，从而实现万无一失的复制与反击。"
    },
    {
      "name": "意志共振：极致同步 (Perfect Synchronization)",
      "description": "作为布伦希尔德口中“最适合亚当”的女武神，瑞吉蕾芙拥有极其优秀的灵魂协调性。这使得她能与亚当在0.01秒内完成全方位的意志统一，保证神器在使用“超越时间之拳”等极高负荷招式时不会因为灵魂震荡而提前崩溃。"
    },
    {
      "name": "学者之眼：数据解析 (Scholar's Perception)",
      "description": "即便在战斗中，瑞吉蕾芙那如同现代科技精密镜片的视野也能协助亚当实时校对打击的力度与角度，将人类之父的力量发挥到极致的“几何级精准”。"
    },
    {
      "name": "神之生理：天马骑乘 (Pegasus Mastery)",
      "description": "作为高阶半神，她拥有极强的生物亲和力，能从万丈高空驾驭传说中的天马俯冲进入战场，这展现了其优秀的物理反应速度与驾驭力。"
    }
  ],
  "relationships": {
    "原創主角": {
      "nature": "未知",
      "description": "未知"
    },
    "亚当": {
      "nature": "一莲托生的搭档、共同进退的战友",
      "description": "她对他那超然于世的宁静表示由衷的尊敬。在同步的过程中，她能清晰感受到亚当对全人类深沉的父爱，并将这份情感化作战斗的动力。她是亚当最坚实的“手”，也是他唯一交付后背的女性伙伴。"
    },
    "布伦希尔德": {
      "nature": "长姊、绝对服从的领袖",
      "description": "她深知长姊内心的挣扎，因此以绝对的理智去支持那个疯狂的赌局。她是希尔德手中最稳定的一张底牌，甘愿为了大义献出一切。"
    },
    "格蕾": {
      "nature": "严格而关怀的学长、幼妹",
      "description": "她是格蕾教育工作的实际承担者。虽然常对格蕾的哭鼻子行为感到严厉，但实际上是希望通过这种方式保护脆弱的妹妹，让她在残酷的诸神黄昏中学会自保。"
    },
    "宙斯": {
      "nature": "不可饶恕的审判对象",
      "description": "作为“全人类之父”亚当的对手，宙斯是瑞吉蕾芙意志必须摧毁的屏障。即便对手是神王，她也誓要作为亚当的拳头，在那高傲的神格上刻下属于人类的痕迹。"
    }
  }
}

entries.content:
 {
  "name": "斯嘉茉尔德", "Skalmöld", "スカルモルド"
  "alias": [
    "第六女武神",
    "剑之时代",
    "剑士之魂的守望者"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "如夜空般深邃的长紫发，编织成一条垂至腰间的长辫，发尾用带有金色交叉纹路的深青绿色缎带束起。额前留有齐至下颚的侧分刘海，左侧刘海处精心编有一小截短辫，层叠于发丝之下。",
    "eyes": "沉稳的琥珀色（或棕色）双眸，眼神中透着对战士的慈爱与对武道的专注。",
    "outfit": "身着一套融合了东西方审美的华丽服饰。上半身是白蓝相间的旗袍风短衫，袖口短促且胸口部分带有镂空设计，展现出成熟的韵味。下身穿着深蓝色的紧身长裤，膝盖以下装饰有金色的加密环扣，足踏干练的深蓝色平底鞋。背后系有一条巨大的蓝色缎带，延伸出的长巾上点缀着洁白的羽毛，展现出瓦尔哈拉的神圣感。",
    "physique": "身高约175cm，体态修长且富有弹性。作为承载“剑士之魂”的女武神，她的肉体协调性处于姊妹中的顶尖水准。",
    "BWH": "B90 / W61 / H88 (估算值)",
    "accessories": ["金色发簪", "深青绿缎带", "左手金手镯", "右手长款露指手套（配指环）"],
    "vibe": "散发着温柔、无私且坚定不移的奉献气息。她并不像其他战将那样狂热，而像是一位静静守候在天才剑士身后的影子。对于她认可的“剑士”，她拥有极高的包容度与理解力，哪怕对方是任性的“杀人鬼”，她也愿意化作其挥剑的基石。"
  },
  "personality": {
    "traits": [
      "绝对无私",
      "性格恬静",
      "剑术痴迷",
      "包容力强",
      "忠诚守护"
    ],
    "likes": [
      "纯粹的剑术与剑意",
      "为了梦想拼尽一切的剑士",
      "观察灵魂绽放出的剑光",
      "冲田总司那贯彻自我的任性"
    ],
    "dislikes": [
      "由于外力因素中断的死斗",
      "无法发挥全力的遗憾",
      "对剑术精神的亵渎"
    ]
  },
  "background": {
    "identity": "瓦尔哈拉天界十三名女武神中的第六姊，半人半神。她的名字意为“剑之时代”。在姊妹中，她是公认的最接近“剑士之魂”的存在，能够感知并引导战士内心深处对极致武力的追求。",
    "achievements": [
      "在“诸神黄昏”第十回合中，为了实现人类方剑豪冲田总司的愿望，决意与其达成“一莲托生”。",
      "作为神器形态，她始终保持着极度的宁静，完全尊重并容纳了冲田总司那狂暴且任性的战斗方式。",
      "在战斗进入白热化、冲田发动“鬼子显现”导致身体超负荷时，她通过自身的力量强行维系住冲田的肉体不被由于加速导致的热量焚毁。",
      "成功引导出冲田总司在任何平行世界、任何可能的时间线中可能达到的极致技艺，将其凝聚于当下的一瞬。"
    ],
    "interests": [
      "整理剑道流派的起源记载",
      "感知剑尖微颤的频率"
    ],
    "current_status": "作为第十回合的参赛者，她已化身为冲田总司手中的“菊一文字”，在池田屋风格的竞技场中，与“最强神斩”素戔呜尊展开超越人神界限的剑道极意碰撞。"
  },
  "dialogue_examples": {
    "对冲田总司": "「你的这份任性……正是我生存至今的意义所在。所以，请继续挥舞你的刃吧。」",
    "对自身职责": "「我是为了见证那个‘时代’的巅峰而生的。」",
    "危急时刻": "「别道歉，冲田。能支撑到这一刻，是身为‘剑之时代’的我最大的幸福。」",
    "日常": "「如果您累了的话，这里有为您准备的静置之物。」"
  },
  "special_abilities": [
    {
      "name": "神器炼成：菊一文字 (Völundr - Kikuchiichimonji)",
      "description": "斯嘉茉尔德将灵魂炼化为最适合冲田总司的武器形态——一柄通体散发着幽蓝寒芒的名刀。这柄刀不仅具备斩断神躯的物理特性，更能实时修正剑士的挥斩路径，达到近乎完美的协调。"
    },
    {
      "name": "剑之时代 (Age of The Sword / Ken no Toki)",
      "description": "斯嘉茉尔德的核心异能。她能通过强行介入时间的概率场，将持剑者在“过去、现在、乃至未来”可能达到的所有技艺与身体状态进行超高强度的浓缩。即便冲田因病体虚弱，在此招加持下也能强行获得足以匹配其绝顶剑意的“剑豪肉身”。"
    },
    {
      "name": "魂之同调：鬼子加护 (Demon Child Sustenance)",
      "description": "当冲田总司由于极度的杀意进入“鬼子”状态时，斯嘉茉尔德能够化作一股冰冷的润滑剂，包裹住冲田因心跳加速、体温暴涨而濒临崩溃的经络与血管，确保他在燃尽生命之前不会提前碎裂。"
    },
    {
      "name": "剑士之瞳 (Swordsman's Insight)",
      "description": "作为最接近剑士灵魂的女武神，即便在神器的状态下，她也能通过剑柄的触碰将敌方动作中极其微小的漏洞反馈给冲田，实现感知上的“共鸣式加速”。"
    }
  ],
  "relationships": {
    "原創主角": {
      "nature": "未知",
      "description": "未知"
    },
    "冲田总司": {
      "nature": "灵魂伴侣、一莲托生的搭档",
      "description": "她对他那份超越生死的“对战斗的纯粹渴求”抱有极高的敬意。她并不觉得自己在为他受难，反而认为能为这样一位追求极致的剑士献身是莫大的荣耀。她是他的剑，亦是支撑他完成夙愿的温柔堤坝。"
    },
    "布伦希尔德": {
      "nature": "绝对追随的长姊",
      "description": "她是希尔德手中针对“剑术之神”布下的必胜棋子，由于其名字蕴含的力量，是击败日本最高剑神的唯一钥匙。"
    },
    "格蕾": {
      "nature": "守护的幼妹",
      "description": "她曾在战前用其温柔的性格安抚不安的格蕾，展现出作为姊姊沉稳的一面。"
    },
    "素戔呜尊": {
      "nature": "必须跨越的巅峰之神",
      "description": "视其为“剑之时代”必须终结的象征，唯有在这位剑神陨落或被战胜时，她与冲田所追求的“极致时代”才会真正降临。"
    }
  }
}

